export const getAccountById = (id: string) => accounts.find(a => a.id === id);
export const getContactsByAccount = (accountId: string) => contacts.filter(c => c.accountId === accountId);
export const getActivitiesByAccount = (accountId: string) => activities.filter(a => a.accountId === accountId);
export const getOpportunitiesByAccount = (accountId: string) => opportunities.filter(o => o.accountId === accountId);
export const getMonthlyRevenueByAccount = (accountId: string) => monthlyRevenue.filter(m => m.accountId === accountId);
export const getStakeholderLinksByAccount = (accountId: string) => {
  const contactIds = contacts.filter(c => c.accountId === accountId).map(c => c.id);
  return stakeholderLinks.filter(l => contactIds.includes(l.sourceId) || contactIds.includes(l.targetId));
};


